/**
 * The scorecard: how well the engine answers what each file is for, and how
 * often it breaks a rule that holds for every file.
 *
 * Two populations:
 *
 *   corpus  every `tests/corpus/<name>.csv` whose `.expect.json` has a
 *           `report` section — real and hand-built files, each with its
 *           questions and ground truth written down by a person.
 *   fuzz    tables generated by `eval/fuzz.mjs` with planted traps and the
 *           truth they were generated with. These carry no questions: they
 *           exist to check the rules on shapes nobody wrote by hand.
 *
 * Each corpus file runs on up to two paths:
 *
 *   noModel    what the deployment does with no model key — the path most
 *              people get, and the one that had no quality test at all.
 *   offered    every question the catalogue suggests, ticked — what the
 *              question card can reach without a model.
 *   withModel  a real model's recorded proposal (tests/corpus/<name>.model.json,
 *              from eval/record-model.mjs), checked and merged as the worker
 *              does, and the report built from its pre-ticked questions.
 *   withBrief  the brief a correct model would return, recorded in the
 *              expectation and verified by `acceptBrief` as the app does.
 *
 * Files go in through `eval/chain.mjs`, the app's own ingest chain, so column
 * names and types are what the app sees.
 *
 *     node eval/scorecard.mjs              summary table
 *     node eval/scorecard.mjs gen_saas     one file, every violation and miss
 *     node eval/scorecard.mjs --markdown   the table for eval/RESULTS.md
 *     node eval/scorecard.mjs --write      lock the result in as the baseline
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { ingest } from './chain.mjs';
import { audit, RULES } from './audit.mjs';
import { answer } from './answers.mjs';
import { fuzzCases } from './fuzz.mjs';
import { scoreModel } from './modelScore.mjs';
import { buildTableModel } from '../lib/tableModel.js';
import { runAnalysis } from '../lib/pipeline.js';
import { profileColumns } from '../lib/chartResolver.js';
import { acceptBrief } from '../lib/datasetBrief.js';
import { acceptModelQuestions, mergeSuggestions } from '../lib/modelQuestions.js';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const CORPUS = path.join(HERE, '..', 'tests', 'corpus');
export const BASELINE = path.join(HERE, 'scorecard.baseline.json');

const ruleCounts = (violations) => {
  const counts = Object.fromEntries(Object.keys(RULES).map((r) => [r, 0]));
  for (const v of violations) counts[v.rule] += 1;
  return counts;
};

/** One report, scored. */
function score(rows, truth, questions, options) {
  let result;
  try {
    result = runAnalysis(rows, options);
  } catch (error) {
    return { error: String(error?.message || error), charts: 0, violations: [], rules: ruleCounts([]), answers: [] };
  }
  const violations = audit(result, rows, truth);
  const answers = (questions || []).map((q) => ({ id: q.id, ...answer(result, rows, q, violations) }));
  return {
    charts: (result.charts || []).filter((c) => c.chart_type !== 'slicer').length,
    violations,
    rules: ruleCounts(violations),
    answers,
    suggestions: result.questions || [],
  };
}

export function scoreCorpus({ only = null } = {}) {
  const out = {};
  for (const file of fs.readdirSync(CORPUS).filter((f) => f.endsWith('.csv')).sort()) {
    const name = file.replace(/\.csv$/, '');
    if (only && !name.includes(only)) continue;
    const spec = JSON.parse(fs.readFileSync(path.join(CORPUS, `${name}.expect.json`), 'utf8'));
    if (!spec.report) continue;
    const { rows } = ingest(fs.readFileSync(path.join(CORPUS, file), 'utf8'));
    const { questions = [], ...truth } = spec.report;
    const model = buildTableModel(rows, { temporal: profileColumns(rows).temporal });
    const paths = { noModel: score(rows, truth, questions, {}) };
    // What the question card offers: the report a reader gets by ticking every
    // question the catalogue suggests. Every one of them has to compile
    // without breaking a rule, not just the recommended few.
    paths.offered = score(rows, truth, questions, { questions: paths.noModel.suggestions });
    // A real model's reading, recorded by eval/record-model.mjs and put
    // through the same gate and merge the worker uses: the report "Choose for
    // me" builds when a model answered.
    const recorded = path.join(CORPUS, `${name}.model.json`);
    if (fs.existsSync(recorded)) {
      const { proposal } = JSON.parse(fs.readFileSync(recorded, 'utf8'));
      const accepted = acceptModelQuestions(proposal, { rows, model, catalogue: paths.noModel.suggestions });
      const merged = mergeSuggestions(paths.noModel.suggestions, accepted);
      paths.withModel = score(rows, truth, questions, { questions: merged.filter((q) => q.recommended) });
      paths.withModel.dropped = accepted.dropped;
    }
    if (spec.brief) {
      const brief = acceptBrief(spec.brief, { rows, profile: profileColumns(rows) });
      paths.withBrief = score(rows, truth, questions, { brief });
    }
    out[name] = { grain: truth.grain, questions: questions.length, paths, model: scoreModel(model, rows, truth) };
  }
  return out;
}

export function scoreFuzz() {
  const out = {};
  for (const c of fuzzCases()) {
    const model = buildTableModel(c.rows, { temporal: profileColumns(c.rows).temporal });
    out[c.name] = { grain: c.truth.grain, trap: c.trap, paths: { noModel: score(c.rows, c.truth, [], {}) }, model: scoreModel(model, c.rows, c.truth) };
  }
  return out;
}

/** The whole scorecard, reduced to what the ratchet compares. */
export function scorecard(options) {
  const corpus = scoreCorpus(options);
  const fuzz = options?.only ? {} : scoreFuzz();
  return { corpus, fuzz };
}

/** What the baseline stores: counts, not titles, so a renamed chart is not a regression. */
export function summarise({ corpus, fuzz }) {
  const pick = (group) =>
    Object.fromEntries(
      Object.entries(group).map(([name, entry]) => [
        name,
        Object.fromEntries([
          ['model', { misses: [...(entry.model || [])].sort() }],
          ...Object.entries(entry.paths).map(([p, s]) => [
            p,
            {
              answered: s.answers.filter((a) => a.answered).map((a) => a.id).sort(),
              rules: Object.fromEntries(Object.entries(s.rules).filter(([, n]) => n > 0)),
              ...(s.error ? { error: s.error } : {}),
            },
          ]),
        ]),
      ])
    );
  return { corpus: pick(corpus), fuzz: pick(fuzz) };
}

/* ── CLI ───────────────────────────────────────────────────────────────── */

function totals(group, p) {
  let files = 0, questions = 0, answered = 0, violations = 0, clean = 0;
  const rules = Object.fromEntries(Object.keys(RULES).map((r) => [r, 0]));
  for (const entry of Object.values(group)) {
    const s = entry.paths[p];
    if (!s) continue;
    files += 1;
    questions += s.answers.length;
    answered += s.answers.filter((a) => a.answered).length;
    violations += s.violations.length;
    if (!s.violations.length) clean += 1;
    for (const [r, n] of Object.entries(s.rules)) rules[r] += n;
  }
  return { files, questions, answered, violations, clean, rules };
}

function printTable(card, markdown) {
  const rulesHeader = Object.keys(RULES);
  const rows = [];
  for (const [name, entry] of Object.entries(card.corpus)) {
    for (const [p, s] of Object.entries(entry.paths)) {
      const got = s.answers.filter((a) => a.answered).length;
      rows.push([name, entry.grain, p, `${got}/${s.answers.length}`, s.charts, ...rulesHeader.map((r) => s.rules[r] || '·'), s.error ? 'THREW' : '']);
    }
  }
  const header = ['file', 'grain', 'path', 'answered', 'charts', ...rulesHeader, ''];
  if (markdown) {
    console.log(`| ${header.join(' | ')} |`);
    console.log(`|${header.map(() => '---').join('|')}|`);
    for (const r of rows) console.log(`| ${r.join(' | ')} |`);
  } else {
    const widths = header.map((h, i) => Math.max(String(h).length, ...rows.map((r) => String(r[i]).length)));
    const line = (r) => r.map((c, i) => String(c).padEnd(widths[i])).join('  ');
    console.log(line(header));
    for (const r of rows) console.log(line(r));
  }
  console.log('');
  for (const p of ['noModel', 'offered', 'withModel', 'withBrief']) {
    const t = totals(card.corpus, p);
    if (!t.files) continue;
    console.log(
      `corpus ${p}: ${t.answered}/${t.questions} questions answered · ${t.clean}/${t.files} files break no rule · ${t.violations} violations (${Object.entries(t.rules).filter(([, n]) => n).map(([r, n]) => `${r} ${n}`).join(', ')})`
    );
  }
  for (const [label, group] of [['corpus', card.corpus], ['fuzz', card.fuzz]]) {
    const entries = Object.values(group);
    if (!entries.length) continue;
    const misses = entries.flatMap((e) => e.model || []);
    const kinds = {};
    for (const m of misses) kinds[m.split(':')[0]] = (kinds[m.split(':')[0]] || 0) + 1;
    const clean = entries.filter((e) => !(e.model || []).length).length;
    console.log(`table model (${label}): ${clean}/${entries.length} tables read correctly · ${misses.length} misses${misses.length ? ` (${Object.entries(kinds).map(([k, n]) => `${k} ${n}`).join(', ')})` : ''}`);
  }
  const f = totals(card.fuzz, 'noModel');
  if (f.files) {
    console.log(
      `fuzz: ${f.clean}/${f.files} tables break no rule · ${f.violations} violations (${Object.entries(f.rules).filter(([, n]) => n).map(([r, n]) => `${r} ${n}`).join(', ')})`
    );
  }
}

function printDetail(card) {
  for (const [name, entry] of Object.entries({ ...card.corpus, ...card.fuzz })) {
    for (const [p, s] of Object.entries(entry.paths)) {
      console.log(`\n${name} · ${p}${entry.trap ? ` · trap: ${entry.trap}` : ''}${s.error ? ` · THREW ${s.error}` : ''}`);
      for (const a of s.answers) console.log(`  ${a.answered ? '✓' : '✗'} ${a.id}: ${a.why}`);
      for (const v of s.violations) console.log(`  ! ${v.rule} ${v.chart}: ${v.detail}`);
      for (const d of s.dropped || []) console.log(`  - model: "${d.claim}" dropped: ${d.reason}`);
    }
    for (const m of entry.model || []) console.log(`  ~ model ${m}`);
  }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const args = process.argv.slice(2);
  const only = args.find((a) => !a.startsWith('--')) || null;
  const card = scorecard({ only });
  if (only) printDetail(card);
  else if (args.includes('--detail')) printDetail(card);
  printTable(card, args.includes('--markdown'));
  if (args.includes('--write')) {
    fs.writeFileSync(BASELINE, JSON.stringify(summarise(card), null, 2) + '\n');
    console.log(`\nbaseline written to ${path.relative(process.cwd(), BASELINE)}`);
  }
}
